module benchmark/solution

import std/json (decode, asArray, getString, getInt, getNumber)
import std/option (Some, None, getOrElse)
import std/result (Ok, Err)
import std/math (intToFloat)
import std/list (map, filter, forEachE)

export func main() -> () ! {IO} {
  let raw = "[{\"id\":1,\"item\":\"apple\",\"qty\":5,\"price\":1.50},{\"id\":2,\"item\":\"banana\",\"qty\":3,\"price\":0.75},{\"id\":3,\"item\":\"orange\",\"qty\":8,\"price\":2.00}]";
  match decode(raw) {
    Ok(json) => match asArray(json) {
      Some(orders) => {
        let totals = map(\order. {
          let item = getOrElse(getString(order, "item"), "");
          let qty = getOrElse(getInt(order, "qty"), 0);
          let price = getOrElse(getNumber(order, "price"), 0.0);
          {item: item, total: intToFloat(qty) * price}
        }, orders);
        let qualifying = filter(\order. order.total > 5.0, totals);
        forEachE(\order. println("${order.item}: ${show(order.total)}"), qualifying)
      },
      None => ()
    },
    Err(_) => ()
  }
}

